def reset_demo_data():
    for file_name in ["students.json", "courses.json", "enrollments.json"]:
        files.delete_file_if_exists(files.make_file_path(DEMO_FOLDER, file_name))

def demo_enrollments(enrollment_service):
    enrollment = enrollment_service.create_enrollment(1, 1)
    say(11, f"student 1 joined course 1 (enrollment {enrollment.enrollment_id})")
    try:
        enrollment_service.create_enrollment(1, 1)
    except ValueError as error:
        say(12, f"rejected double join -> {error}")
    try:
        enrollment_service.create_enrollment(2, 1)
    except ValueError as error:
        say(13, f"rejected full course -> {error}")
    enrollment_service.update_enrollment(1, 2)
    say(14, f"moved enrollment 1 to course {enrollment_service.find_enrollment_by_id(1).course_id}")

def start_program():
    menu = Menu("data")
    menu.run()

def to_dict(self):
    return {
        "id": self.enrollment_id,
        "student_id": self.student_id,
        "course_id": self.course_id,
    }

def to_dict(self):
    return {
        "id": self.student_id,
        "name": self.name,
        "email": self.email,
        "phone": self.phone,
    }

def check_course_fields(self, title, max_seats):
    if not rules.is_valid_title(title):
        raise ValueError("A course needs a title.")
    if not rules.is_valid_seat_count(max_seats):
        raise ValueError(
            f"Seats must be a number from {rules.MINIMUM_SEATS} to {rules.MAXIMUM_SEATS}."
        )

def find_course_by_id(self, course_id):
    course = self.repository.read_course_by_id(course_id)
    if course is None:
        raise ValueError(f"Course {course_id} was not found.")
    return course

def delete_course(self, course_id):
    self.find_course_by_id(course_id)
    self.repository.remove_course(course_id)

def count_enrollments_for_course(self, course_id):
    total = 0
    for enrollment in self.repository.read_all_enrollments():
        if enrollment.course_id == course_id:
            total = total + 1
    return total

def check_student_exists(self, student_id):
    if self.student_repository.read_student_by_id(student_id) is None:
        raise ValueError(f"Student {student_id} was not found.")

def find_course_or_fail(self, course_id):
    course = self.course_repository.read_course_by_id(course_id)
    if course is None:
        raise ValueError(f"Course {course_id} was not found.")
    return course

def check_enrollment_rules(self, student_id, course_id):
    self.check_student_exists(student_id)
    course = self.find_course_or_fail(course_id)
    enrollments = self.repository.read_all_enrollments()
    if rules.is_duplicate_enrollment(enrollments, student_id, course_id):
        raise ValueError("This student already joined this course.")
    seats_taken = self.count_enrollments_for_course(course_id)
    if rules.is_course_full(seats_taken, course.max_seats):
        raise ValueError("This course is full.")

def find_enrollment_by_id(self, enrollment_id):
    enrollment = self.repository.read_enrollment_by_id(enrollment_id)
    if enrollment is None:
        raise ValueError(f"Enrollment {enrollment_id} was not found.")
    return enrollment

def delete_enrollment(self, enrollment_id):
    self.find_enrollment_by_id(enrollment_id)
    self.repository.remove_enrollment(enrollment_id)

def __init__(self, data_folder):
    self.repository = StudentRepository(data_folder)
    self.enrollment_repository = EnrollmentRepository(data_folder)

def check_student_fields(self, name, email):
    if not rules.is_valid_name(name):
        raise ValueError("A student needs a name.")
    if not rules.is_valid_email(email):
        raise ValueError("A student needs an email that contains @.")

def find_student_by_id(self, student_id):
    student = self.repository.read_student_by_id(student_id)
    if student is None:
        raise ValueError(f"Student {student_id} was not found.")
    return student

def find_record_by_id(self, record_id):
    for record in self.load_all_records():
        if record["id"] == record_id:
            return record
    return None

def replace_record(self, record_id, new_record):
    records = self.load_all_records()
    was_found = False
    for position in range(len(records)):
        if records[position]["id"] == record_id:
            records[position] = new_record
            was_found = True
    self.save_all_records(records)
    return was_found

def remove_record_by_id(self, record_id):
    records = self.load_all_records()
    kept_records = []
    for record in records:
        if record["id"] != record_id:
            kept_records.append(record)
    self.save_all_records(kept_records)
    return len(kept_records) < len(records)

def read_all_courses(self):
    courses = []
    for record in self.load_all_records():
        courses.append(self.convert_record_to_course(record))
    return courses

def read_course_by_id(self, course_id):
    record = self.find_record_by_id(course_id)
    if record is None:
        return None
    return self.convert_record_to_course(record)

def read_all_enrollments(self):
    enrollments = []
    for record in self.load_all_records():
        enrollments.append(self.convert_record_to_enrollment(record))
    return enrollments

def read_enrollment_by_id(self, enrollment_id):
    record = self.find_record_by_id(enrollment_id)
    if record is None:
        return None
    return self.convert_record_to_enrollment(record)

def remove_enrollments_for_student(self, student_id):
    kept_records = []
    for record in self.load_all_records():
        if record["student_id"] != student_id:
            kept_records.append(record)
    self.save_all_records(kept_records)

def convert_record_to_student(self, record):
    phone = record.get("phone", "")
    return Student(record["id"], record["name"], record["email"], phone)

def read_all_students(self):
    students = []
    for record in self.load_all_records():
        students.append(self.convert_record_to_student(record))
    return students

def read_student_by_id(self, student_id):
    record = self.find_record_by_id(student_id)
    if record is None:
        return None
    return self.convert_record_to_student(record)

def __init__(self, data_folder):
    self.actions = MenuActions(data_folder)
    self.choices = self.build_choices()

def run_choice(self, choice):
    action = self.choices[choice]
    try:
        action()
    except ValueError as error:
        printer.print_message(f"Problem: {error}")

def run(self):
    keep_going = True
    while keep_going:
        self.show_menu()
        choice = printer.ask_text("Your choice:")
        if choice == "0":
            keep_going = False
        elif choice in self.choices:
            self.run_choice(choice)
        else:
            printer.print_message("Please type a number from the menu.")
    printer.print_message("Goodbye!")

def handle_find_student(self):
    student_id = printer.ask_number("Student id:")
    printer.print_student(self.student_service.find_student_by_id(student_id))

def handle_find_course(self):
    course_id = printer.ask_number("Course id:")
    printer.print_course(self.course_service.find_course_by_id(course_id))

def handle_find_enrollment(self):
    enrollment_id = printer.ask_number("Enrollment id:")
    printer.print_enrollment(self.enrollment_service.find_enrollment_by_id(enrollment_id))

def ask_text(question):
    answer = input(question + " ")
    return answer.strip()

def ask_number(question):
    answer = ask_text(question)
    try:
        return int(answer)
    except ValueError:
        return None

def print_students(students):
    if len(students) == 0:
        print("  (no students yet)")
    for student in students:
        print_student(student)

def print_courses(courses):
    if len(courses) == 0:
        print("  (no courses yet)")
    for course in courses:
        print_course(course)

def print_enrollment(enrollment):
    print(
        f"  [{enrollment.enrollment_id}] student {enrollment.student_id}"
        f" joined course {enrollment.course_id}"
    )

def print_enrollments(enrollments):
    if len(enrollments) == 0:
        print("  (no enrollments yet)")
    for enrollment in enrollments:
        print_enrollment(enrollment)

def read_json_file(file_path):
    if not os.path.exists(file_path):
        return []
    with open(file_path, "r") as json_file:
        return json.load(json_file)

def write_json_file(file_path, records):
    folder = os.path.dirname(file_path)
    if folder != "":
        os.makedirs(folder, exist_ok=True)
    with open(file_path, "w") as json_file:
        json.dump(records, json_file, indent=2)

def delete_file_if_exists(file_path):
    if os.path.exists(file_path):
        os.remove(file_path)

def make_next_id(records):
    highest_id = 0
    for record in records:
        if record["id"] > highest_id:
            highest_id = record["id"]
    return highest_id + 1

def has_text(value):
    if not isinstance(value, str):
        return False
    return value.strip() != ""

def is_valid_email(email):
    if not has_text(email):
        return False
    for character in email:
        if character == "@":
            return True
    return False

def is_valid_seat_count(seats):
    if not isinstance(seats, int):
        return False
    return seats >= MINIMUM_SEATS and seats <= MAXIMUM_SEATS

def is_duplicate_enrollment(enrollments, student_id, course_id):
    for enrollment in enrollments:
        if enrollment.student_id == student_id and enrollment.course_id == course_id:
            return True
    return False

def setUp(self):
    self.folder = tempfile.mkdtemp()
    self.course_service = CourseService(self.folder)

def test_create_course_gets_first_id(self):
    course = self.course_service.create_course("Python", 30)
    self.assertEqual(course.course_id, 1)

def test_create_course_rejects_empty_title(self):
    with self.assertRaises(ValueError):
        self.course_service.create_course("", 30)

def test_create_course_rejects_zero_seats(self):
    with self.assertRaises(ValueError):
        self.course_service.create_course("Python", 0)

def test_create_course_rejects_too_many_seats(self):
    with self.assertRaises(ValueError):
        self.course_service.create_course("Python", 1000)

def test_create_course_rejects_text_seats(self):
    with self.assertRaises(ValueError):
        self.course_service.create_course("Python", "many")

def test_create_enrollment_works(self):
    enrollment = self.enrollment_service.create_enrollment(1, 1)
    self.assertEqual(enrollment.enrollment_id, 1)

def test_create_enrollment_rejects_missing_student(self):
    with self.assertRaises(ValueError):
        self.enrollment_service.create_enrollment(99, 1)

def test_create_enrollment_rejects_missing_course(self):
    with self.assertRaises(ValueError):
        self.enrollment_service.create_enrollment(1, 99)

def setUp(self):
    self.folder = tempfile.mkdtemp()
    self.student_service = StudentService(self.folder)

def test_create_student_gets_first_id(self):
    student = self.student_service.create_student("Ann", "ann@example.com", "555-0100")
    self.assertEqual(student.student_id, 1)

def test_create_student_rejects_email_without_at_sign(self):
    with self.assertRaises(ValueError):
        self.student_service.create_student("Ann", "ann.example.com", "555-0100")

def test_create_student_rejects_empty_name(self):
    with self.assertRaises(ValueError):
        self.student_service.create_student("   ", "ann@example.com", "555-0100")

def test_count_students_returns_number_of_students(self):
    self.student_service.create_student("Ann", "ann@example.com", "555-0100")
    self.assertEqual(self.student_service.count_students(), 1)

def test_find_student_by_id_missing_raises(self):
    with self.assertRaises(ValueError):
        self.student_service.find_student_by_id(99)
